import{_ as t,o,c as a,a5 as i}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"AI Video Generation Architecture & Model Evaluation Report","description":"","frontmatter":{},"headers":[],"relativePath":"ai-models/video-generation-research-report.md","filePath":"ai-models/video-generation-research-report.md"}'),n={name:"ai-models/video-generation-research-report.md"};function r(d,e,s,l,c,g){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="ai-video-generation-architecture-model-evaluation-report" tabindex="-1">AI Video Generation Architecture &amp; Model Evaluation Report <a class="header-anchor" href="#ai-video-generation-architecture-model-evaluation-report" aria-label="Permalink to &quot;AI Video Generation Architecture &amp; Model Evaluation Report&quot;">​</a></h1><p>&gt; <a href="./../">&lt;&lt; Knowledge Base Home</a> · <a href="./README.html">AI Models &amp; Research</a> · <a href="./../architecture/ai-service-architecture.html">AI Service Architecture</a></p><p>This specification documents BrandHub&#39;s end-to-end AI video generation research and final production architecture powering <strong>AI Video Generation (<code>FR 3.7.9</code>–<code>3.7.11</code>)</strong> and <strong>Product Video Studio (<code>FR 3.6.34</code>–<code>3.6.35</code>)</strong>:</p><ol><li><strong>Phase 1 Evaluation</strong>: Commercial API benchmarking (<code>veo-3.1-flash</code>) across <strong>30 standardized marketing prompt templates</strong>.</li><li><strong>Phase 2 Production Architecture</strong>: Self-hosted <strong>Wan 2.2 Fun VACE 14B + Qwen Image 2.1 + Wan 2.2 S2V 14B</strong> on Vast.ai GPU workers (<code>gpu-workers/wan-vace/</code>), orchestrated by <code>brandhub-ai-service/app/services/ltx_director.py</code> and paired with FFmpeg server-side timeline rendering (<code>brandhub-edit-video</code>).</li></ol><hr><h2 id="_1-phase-1-commercial-api-evaluation-veo-3-1-flash" tabindex="-1">1. Phase 1 Commercial API Evaluation (<code>veo-3.1-flash</code>) <a class="header-anchor" href="#_1-phase-1-commercial-api-evaluation-veo-3-1-flash" aria-label="Permalink to &quot;1. Phase 1 Commercial API Evaluation (`veo-3.1-flash`)&quot;">​</a></h2><p>During AI Iteration 1 &amp; 4, Google Veo (<code>veo-3.1-flash</code>) was evaluated as an API-first baseline for Text-to-Video and Image-to-Video generation:</p><ul><li><strong>Pricing Baseline</strong>: <code>$0.40</code> per 5s clip at <code>1080p</code> (<code>$0.15</code> per 5s clip at <code>720p</code>).</li><li><strong>API Constraints</strong>: 4s / 6s / 8s single-call clip cap, <code>16:9</code> or <code>9:16</code> aspect ratios, <code>24 FPS</code>.</li></ul><h3 id="multi-segment-chaining-cost-projection-api-baseline" tabindex="-1">Multi-Segment Chaining Cost Projection (API Baseline) <a class="header-anchor" href="#multi-segment-chaining-cost-projection-api-baseline" aria-label="Permalink to &quot;Multi-Segment Chaining Cost Projection (API Baseline)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Target Duration</th><th style="text-align:left;">API Chaining Strategy</th><th style="text-align:left;">1080p Cost</th><th style="text-align:left;">720p Cost</th><th style="text-align:left;">Estimated Render Latency</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>5 seconds</strong></td><td style="text-align:left;">1 API call</td><td style="text-align:left;"><code>$0.40</code></td><td style="text-align:left;"><code>$0.15</code></td><td style="text-align:left;">~20s</td></tr><tr><td style="text-align:left;"><strong>10 seconds</strong></td><td style="text-align:left;">2 chained calls (1 stitch)</td><td style="text-align:left;"><code>$0.80</code></td><td style="text-align:left;"><code>$0.30</code></td><td style="text-align:left;">~45s</td></tr><tr><td style="text-align:left;"><strong>15 seconds</strong></td><td style="text-align:left;">3 chained calls (2 stitches)</td><td style="text-align:left;"><code>$1.20</code></td><td style="text-align:left;"><code>$0.45</code></td><td style="text-align:left;">~75s</td></tr><tr><td style="text-align:left;"><strong>20 seconds</strong></td><td style="text-align:left;">4 chained calls (3 stitches)</td><td style="text-align:left;"><code>$1.60</code></td><td style="text-align:left;"><code>$0.60</code></td><td style="text-align:left;">~110s</td></tr></tbody></table><h3 id="why-production-migrated-beyond-pure-veo-chaining" tabindex="-1">Why Production Migrated Beyond Pure Veo Chaining <a class="header-anchor" href="#why-production-migrated-beyond-pure-veo-chaining" aria-label="Permalink to &quot;Why Production Migrated Beyond Pure Veo Chaining&quot;">​</a></h3><p>While last-frame feedback chaining solved basic continuity, commercial API calls suffered from three production blockers for Vietnamese e-commerce agencies:</p><ol><li><strong>Packaging &amp; Label Drift</strong>: Pure text/single-frame I2V drifted brand logos and Vietnamese packaging typography across cuts.</li><li><strong>Strict Commercial Safety False Positives</strong>: Benign skincare/fashion studio shots were intermittently rejected by opaque upstream safety filters.</li><li><strong>Unit Economics at 15–21s</strong>: Multi-segment commercial TVCs cost <code>$1.20–$1.60</code> per render without deterministic start/end keyframe locking (<code>FLF2V</code>) or lip-synced Vietnamese speech (<code>S2V</code>).</li></ol><hr><h2 id="_2-production-video-architecture-wan-2-2-fun-vace-14b-qwen-image-2-1-s2v" tabindex="-1">2. Production Video Architecture: Wan 2.2 Fun VACE 14B + Qwen Image 2.1 + S2V <a class="header-anchor" href="#_2-production-video-architecture-wan-2-2-fun-vace-14b-qwen-image-2-1-s2v" aria-label="Permalink to &quot;2. Production Video Architecture: Wan 2.2 Fun VACE 14B + Qwen Image 2.1 + S2V&quot;">​</a></h2><p>In production, <code>brandhub-ai-service</code> (<code>app/services/ltx_director.py</code>) acts as an <strong>AI Director</strong>, compiling user briefs and product/ambassador photos into a schema-validated JSON shooting script executed by the ComfyUI GPU worker (<code>gpu-workers/wan-vace/</code>).</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    BIZ[&quot;brandhub-business-service&lt;br/&gt;(ProductVideoStore + AI Credits)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DIR[&quot;brandhub-ai-service&lt;br/&gt;ltx_director.py (Claude Director)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    VACE[&quot;Vast.ai GPU Worker (wan-vace)&lt;br/&gt;Qwen Image 2.1 + Wan 2.2 VACE 14B + S2V&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    FFM[&quot;FFmpeg Postprocess&lt;br/&gt;add_music() + brandhub-edit-video (:8095)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S3[&quot;AWS S3 Media Bucket&quot;]</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    BIZ --&gt;|&quot;Reserve credits + submit brief&quot;| DIR</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DIR --&gt;|&quot;Validate script.schema.json&lt;br/&gt;POST multipart /jobs&quot;| VACE</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    VACE --&gt;|&quot;Poll /jobs/{id} → silent/S2V MP4&quot;| DIR</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DIR --&gt;|&quot;Mix CC0 WAV (-af afade) + faststart&quot;| FFM</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    FFM --&gt;|&quot;Upload final MP4 + thumbnail&quot;| S3</span></span></code></pre></div><h3 id="_2-1-core-runtime-constants-guardrails-ltx-director-py-↔-build-vace-flow-py" tabindex="-1">2.1 Core Runtime Constants &amp; Guardrails (<code>ltx_director.py</code> ↔ <code>build_vace_flow.py</code>) <a class="header-anchor" href="#_2-1-core-runtime-constants-guardrails-ltx-director-py-↔-build-vace-flow-py" aria-label="Permalink to &quot;2.1 Core Runtime Constants &amp; Guardrails (`ltx_director.py` ↔ `build_vace_flow.py`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Parameter</th><th style="text-align:left;">Production Value</th><th style="text-align:left;">Enforcement Rule</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Frame Rate (<code>FPS</code>)</strong></td><td style="text-align:left;"><code>16 FPS</code></td><td style="text-align:left;">Deterministic timeline grid shared between <code>ltx_director.py</code> and ComfyUI <code>WanVaceToVideo</code>.</td></tr><tr><td style="text-align:left;"><strong>Segment Length (<code>DEFAULT_FRAMES</code>)</strong></td><td style="text-align:left;"><code>85 frames</code> (<code>5.31s</code>)</td><td style="text-align:left;">Every segment frame count MUST satisfy <code>4n + 1</code> (<code>check_script()</code> rejects invalid counts before touching GPU).</td></tr><tr><td style="text-align:left;"><strong>Chained Seam (<code>OVERLAP</code>)</strong></td><td style="text-align:left;"><code>8 frames</code> (<code>0.5s</code>)</td><td style="text-align:left;">When <code>start = &quot;prev&quot;</code>, the last 8 frames of segment <code>i-1</code> condition the VACE control stream of segment <code>i</code>.</td></tr><tr><td style="text-align:left;"><strong>Total Output Window</strong></td><td style="text-align:left;"><code>15.0s – 21.0s</code></td><td style="text-align:left;">Validated via <code>MIN_SECONDS = 15</code>, <code>MAX_SECONDS = 21</code> prior to worker submission.</td></tr><tr><td style="text-align:left;"><strong>Resolutions (<code>SIZES</code>)</strong></td><td style="text-align:left;"><code>9:16</code> (<code>576×1024</code>), <code>16:9</code> (<code>1024×576</code>)</td><td style="text-align:left;">Native vertical Reels/TikTok/Shorts and horizontal widescreen TVC profiles.</td></tr><tr><td style="text-align:left;"><strong>Director Fallback</strong></td><td style="text-align:left;">Anthropic API → Claude CLI</td><td style="text-align:left;">Primary <code>generate_claude()</code> call with automatic fallback to <code>claude_cli()</code> (<code>VIDEO_DIRECTOR_MODEL</code>, stdin-isolated).</td></tr></tbody></table><h3 id="_2-2-multi-stage-gpu-synthesis-pipeline-gpu-workers-wan-vace" tabindex="-1">2.2 Multi-Stage GPU Synthesis Pipeline (<code>gpu-workers/wan-vace/</code>) <a class="header-anchor" href="#_2-2-multi-stage-gpu-synthesis-pipeline-gpu-workers-wan-vace" aria-label="Permalink to &quot;2.2 Multi-Stage GPU Synthesis Pipeline (`gpu-workers/wan-vace/`)&quot;">​</a></h3><ol><li><strong>4-Angle Qwen Turnaround Sheet (<code>views</code>)</strong>: Qwen Image 2.1 synthesizes consistent front/side/three-quarter/detail product reference sheets from <code>reference_image</code> (attachment 1) so packaging geometry never warps during camera orbit.</li><li><strong>Storyboard Panel Grids (<code>K0..K3</code> or <code>K0..K7</code>)</strong>: Qwen Image Edit renders one or two <code>2×2</code> contact sheets (<code>storyboard_prompt</code> / <code>storyboard_prompts</code>). When a Virtual Ambassador or model photo is supplied (<code>character_image_base64</code> / <code>extra_images</code>), it is injected as <strong>image 3</strong> so every panel preserves exact facial identity.</li><li><strong>Wan 2.2 Fun VACE 14B Motion Synthesis</strong>: Each segment runs either <strong>First-Last-Frame-to-Video (<code>FLF2V</code>)</strong> between storyboard panels (<code>start: K_a</code>, <code>end_panel: K_b</code>) or <strong>seam-chained continuation</strong> (<code>start: &quot;prev&quot;</code>) with <code>8</code>-frame latent overlap.</li><li><strong>Wan 2.2 S2V 14B Lip-Sync (<code>ugc</code> genre)</strong>: For talking-head UGC scripts, TTS audio drives <code>WanSoundImageToVideo</code> for frame-accurate Vietnamese lip synchronization.</li><li><strong>Audio Mastering &amp; Studio Timeline (<code>add_music</code> &amp; <code>brandhub-edit-video</code>)</strong>: <code>ltx_director.py</code> mixes looped CC0 background tracks (<code>app/resources/product-video/music/*.wav</code>, <code>0.5s</code> fade-in, <code>1.5s</code> fade-out, <code>aac 192k</code>, <code>+faststart</code>). Users can subsequently refine cuts, captions, and overlays in the Web Video Studio backed by <code>brandhub-edit-video</code> (<code>:8095</code>).</li></ol><hr><h2 id="_3-prompt-engineering-rules-30-prompt-benchmark-summary" tabindex="-1">3. Prompt Engineering Rules &amp; 30-Prompt Benchmark Summary <a class="header-anchor" href="#_3-prompt-engineering-rules-30-prompt-benchmark-summary" aria-label="Permalink to &quot;3. Prompt Engineering Rules &amp; 30-Prompt Benchmark Summary&quot;">​</a></h2><h3 id="_3-1-five-production-prompt-rules-applied-in-director-prompt-md-prompt-rules-wan-md" tabindex="-1">3.1 Five Production Prompt Rules (Applied in <code>DIRECTOR_PROMPT.md</code> &amp; <code>prompt-rules-wan.md</code>) <a class="header-anchor" href="#_3-1-five-production-prompt-rules-applied-in-director-prompt-md-prompt-rules-wan-md" aria-label="Permalink to &quot;3.1 Five Production Prompt Rules (Applied in `DIRECTOR_PROMPT.md` &amp; `prompt-rules-wan.md`)&quot;">​</a></h3><ol><li><strong>Linear Scene Ordering</strong>: Structure every segment prompt strictly as <em>Environment/Stage → Hero Product/Subject → Single Physical Action → Camera Trajectory → Lighting &amp; Material Texture</em>.</li><li><strong>Zero Meta-Instruction Noise</strong>: Never use conversational filler (<code>&quot;Please generate a video of...&quot;</code>); open directly with framing and physical optics (<code>&quot;Close-up 50mm studio shot of...&quot;</code>).</li><li><strong>Physical Surface &amp; Lighting Anchors</strong>: Specify tangible lighting and surface cues (<em>softbox key light, specular glass highlight, matte anodized aluminum, natural window rim light</em>) while avoiding synthetic CGI buzzwords that cause plastic skin.</li><li><strong>Explicit Cinematographic Camera Verbs</strong>: Parameterize camera motion with unambiguous verbs (<em>slow dolly in, locked-off tripod, gentle pan right, tabletop macro push</em>)—see <a href="./camera-movement-ai-prompts.html">camera-movement-ai-prompts.md</a>.</li><li><strong>One Core Action per 5-Second Beat</strong>: Restrict each <code>85</code>-frame (<code>5.3s</code>) segment to a single physical action; never combine rapid subject locomotion with simultaneous zoom/orbit, which causes limb or label warping.</li></ol><h3 id="_3-2-benchmark-across-30-standardized-marketing-prompts" tabindex="-1">3.2 Benchmark Across 30 Standardized Marketing Prompts <a class="header-anchor" href="#_3-2-benchmark-across-30-standardized-marketing-prompts" aria-label="Permalink to &quot;3.2 Benchmark Across 30 Standardized Marketing Prompts&quot;">​</a></h3><p>All 30 standardized marketing video prompt templates were benchmarked for render latency, surface/motion fidelity (<code>1–5</code>), and per-segment cost during Phase 1 (<code>video_templates.py</code> baseline) prior to codifying the VACE storyboard presets:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Template ID</th><th style="text-align:left;">Template Archetype</th><th style="text-align:center;">Avg Render Time (5s)</th><th style="text-align:center;">Visual Fidelity (<code>1–5</code>)</th><th style="text-align:center;">Baseline API Cost</th><th style="text-align:left;">Key Engineering Finding</th></tr></thead><tbody><tr><td style="text-align:left;"><code>01</code></td><td style="text-align:left;"><strong>Product Intro — Static Hero</strong></td><td style="text-align:center;"><code>18s</code></td><td style="text-align:center;"><code>4.8</code></td><td style="text-align:center;"><code>$0.40</code></td><td style="text-align:left;">Crispest packaging typography and specular material fidelity; adopted as <code>K0</code> opening anchor.</td></tr><tr><td style="text-align:left;"><code>02</code></td><td style="text-align:left;"><strong>Product Intro — Slow Pan</strong></td><td style="text-align:center;"><code>21s</code></td><td style="text-align:center;"><code>4.5</code></td><td style="text-align:center;"><code>$0.40</code></td><td style="text-align:left;">Smooth horizontal parallax without edge warping when subject remains stationary.</td></tr><tr><td style="text-align:left;"><code>05</code></td><td style="text-align:left;"><strong>Lifestyle — Dynamic Zoom In</strong></td><td style="text-align:center;"><code>25s</code></td><td style="text-align:center;"><code>4.2</code></td><td style="text-align:center;"><code>$0.40</code></td><td style="text-align:left;">Minor focus softening in final frames under unconstrained I2V; resolved in VACE via <code>end_panel</code> FLF2V lock.</td></tr><tr><td style="text-align:left;"><code>12</code></td><td style="text-align:left;"><strong>Unboxing — Locked Tabletop</strong></td><td style="text-align:center;"><code>19s</code></td><td style="text-align:center;"><code>4.9</code></td><td style="text-align:center;"><code>$0.40</code></td><td style="text-align:left;">Natural hand-object interaction and realistic studio shadow falloff (<code>example_unbox_chained.json</code>).</td></tr><tr><td style="text-align:left;"><code>01–30</code></td><td style="text-align:left;"><strong>Full 30-Template Suite (Aggregate)</strong></td><td style="text-align:center;"><code>~20s</code> / beat</td><td style="text-align:center;"><strong><code>4.6</code> avg</strong></td><td style="text-align:center;"><code>$0.40</code> / beat</td><td style="text-align:left;">Static &amp; single-axis camera moves (<code> dolly</code>, <code>pan</code>, <code>locked</code>) consistently outperform compound camera + subject motion.</td></tr></tbody></table><hr><h2 id="_4-operational-risks-mitigations" tabindex="-1">4. Operational Risks &amp; Mitigations <a class="header-anchor" href="#_4-operational-risks-mitigations" aria-label="Permalink to &quot;4. Operational Risks &amp; Mitigations&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Risk / Failure Mode</th><th style="text-align:left;">Root Cause</th><th style="text-align:left;">Production Mitigation</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Subject / Label Warping on Compound Motion</strong></td><td style="text-align:left;">Simultaneous fast subject movement (<code>subject_walk</code>) + camera zoom degrades latent geometry in trailing frames.</td><td style="text-align:left;">Lock tripod camera when subject moves rapidly, or lock product stationary during camera orbit + supply 4-angle Qwen turnaround sheet.</td></tr><tr><td style="text-align:left;"><strong>Malformed LLM Shooting Script</strong></td><td style="text-align:left;">LLM outputs invalid frame counts (not <code>4n+1</code>), out-of-range panel indices, or total duration outside <code>15–21s</code>.</td><td style="text-align:left;"><code>check_script()</code> validates <code>script.schema.json</code> + exact frame/panel math in <code>brandhub-ai-service</code> before allocating GPU worker time.</td></tr><tr><td style="text-align:left;"><strong>GPU Cold-Start / Spot Interruption</strong></td><td style="text-align:left;">Ephemeral Vast.ai GPU worker offline or restarting.</td><td style="text-align:left;">Credit reservation in PostgreSQL (<code>ai_credit_reservations</code> + <code>product_video_attempts</code>) only captures credits upon verified output delivery; failed jobs release reserved credits automatically.</td></tr></tbody></table>',31)])])}const u=t(n,[["render",r]]);export{h as __pageData,u as default};
